package local.lito381.server;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.lang.ref.*;import java.lang.reflect.*;
/** Executes original stamp, Batch, status Task and final cipher against detached arena actors. */
public final class SourcePoisonAudiencePlan {
 static int cases,stamps,captures,frames,waits,discoveryWaits;static void check(boolean b,String s){if(!b)throw new AssertionError(s);cases++;}static void set(Object o,String k,Object v)throws Exception{SourceSignedRecoveryPlan.set(o,k,v);}static Object state(ClientSession pc){return SourceElementTransportPlan.state(pc);}
 static NativeSourceArenaPoison.Proof proof(SourceElementTransportPlan.Fixture f){return (NativeSourceArenaPoison.Proof)CombatAccess.field(f.update(),NativeSourceArenaPoison.STAMP);}
 static NativeSourceArenaPoison.Viewer viewer(NativeSourceArenaPoison.Proof p,ClientSession pc){return p.viewers().stream().filter(v->v.pc().get()==pc).findFirst().orElseThrow();}
 static void stamp(SourceElementTransportPlan.Fixture f){synchronized(f.base().base().hub()){synchronized(f.base().encounter()){NativeSourceArenaPoison.stamp(f.update(),f.base().actor());}}stamps++;}
 static SourceElementTransportPlan.Queued queue(SourceElementTransportPlan.Fixture f,ClientSession pc,byte[] packet)throws Exception{var q=SourceElementTransportPlan.status(f,pc,packet,null);check(q.status().proof()==proof(f)&&q.status().receiver()==pc,"original status Task carries actual original stamp proof");captures++;return q;}
 static void run(SourceElementTransportPlan.Queued q)throws Exception{SourceElementTransportPlan.run(q.task());}
 static void waitReject(SourceElementTransportPlan.Queued q,Runnable mutation,String name)throws Exception{var pc=q.status().receiver();var socket=SourceNpcHpOutputPlan.io(pc);long cipher=((Protocol.CipherState)CombatAccess.field(pc,"outgoing")).value();var began=new CountDownLatch(1);var failure=new AtomicReference<Throwable>();var sentinel=SourceFirstPlayersPlan.context();var restored=new AtomicBoolean();var worker=new Thread(()->{try{NativeAreaMaterialAction.current.set(sentinel);began.countDown();run(q);restored.set(NativeAreaMaterialAction.current.get()==sentinel);}catch(Throwable e){failure.set(e);}finally{NativeAreaMaterialAction.current.remove();}},"poison-first-audience-final-status-wait");synchronized(pc){worker.start();check(began.await(3,TimeUnit.SECONDS),"status worker started "+name);SourceElementAudiencePlan.blocked(worker,"original status final receiver monitor "+name);mutation.run();}worker.join(3000);check(!worker.isAlive()&&failure.get()==null&&restored.get()&&socket.bytes.size()==0&&((Protocol.CipherState)CombatAccess.field(pc,"outgoing")).value()==cipher,"first status identity fences before cipher and restores TLS "+name);waits++;}
 static void firstWait(boolean timed)throws Exception{var f=SourceElementTransportPlan.fixture(timed);var b=f.base().base();var began=new CountDownLatch(1);var failure=new AtomicReference<Throwable>();var worker=new Thread(()->{try{began.countDown();stamp(f);}catch(Throwable e){failure.set(e);}},"poison-stamp-first-discovery-wait");synchronized(CombatPoisonAtomic.status(b.observer())){worker.start();check(began.await(3,TimeUnit.SECONDS),"stamp discovery worker started");SourceElementAudiencePlan.blocked(worker,"original stamp first audience before late binding loop");NativePlayerCommit.scene(b.viewer(),2L,"currentRoomId");NativePlayerCommit.scene(b.viewer(),1L,"currentRoomId");}worker.join(3000);check(!worker.isAlive()&&failure.get()==null,"original stamp completes after discovery wait");var p=proof(f);var v=viewer(p,b.viewer());check(NativeAcceptedFreezeMutation.roleFrame(v.binding(),b.viewer())&&!NativeSourcePoisonAudience.value(v.nativeSourcePoisonAudience,b.viewer(),v.binding()),"later original Viewer binding cannot adopt new role after first discovery ABA");var packet=Protocol.poison(f.base().aim().npc().id(),0);var q=queue(f,b.viewer(),packet);var socket=SourceNpcHpOutputPlan.io(b.viewer());run(q);check(socket.bytes.size()==0&&!NativeSourceArenaPoison.current(new NativeSourceArenaPoison.Output(p,b.viewer(),v.binding())),"both original poison final proof paths reject first role retirement");discoveryWaits++;}
 static void test(boolean timed)throws Exception{var f=SourceElementTransportPlan.fixture(timed);var b=f.base().base();CombatAccess.set(state(b.observer()),"sourceNpcOwner",null);CombatAccess.set(state(b.viewer()),"sourceNpcOwner",null);stamp(f);var p=proof(f);check(p!=f.proof()&&p.viewers().size()==4&&p.acceptedLife()==f.proof().acceptedLife()&&p.actor()==f.base().actor()&&p.lease()==f.lease(),"actual original stamp keeps original NPC/lease/accepted provenance and room content");var seen=viewer(p,b.observer());var original=(NativeSourceElementAudience.Receiver)seen.nativeSourcePoisonAudience;check(original.life()==null&&original.observer()&&NativeSourceControlledDisplay.rawLife(b.observer())==null,"first nullable observer has no new actor token");var live=viewer(p,b.viewer());var liveFirst=(NativeSourceElementAudience.Receiver)live.nativeSourcePoisonAudience;check(liveFirst.life()!=null&&liveFirst.life()==NativeSourceControlledDisplay.rawLife(b.viewer()),"living status receiver canonical life initializes only at first discovery");for(var v:p.viewers()){check(v.nativeSourcePoisonAudience instanceof NativeSourceElementAudience.Receiver,"retained Viewer holds individual immutable receiver, not full room list/Context");check(((NativeSourceElementAudience.Receiver)v.nativeSourcePoisonAudience).status().get()==CombatAccess.field(v.pc().get(),"timedStatus"),"first status identity is weak and exact");}
  var legacy=new NativeSourceArenaPoison.Viewer(seen.pc(),seen.binding());var marked=new NativeSourceArenaPoison.Viewer(seen.pc(),seen.binding(),seen.nativeSourcePoisonAudience);check(legacy.nativeSourcePoisonAudience==null&&marked.equals(legacy)&&marked.hashCode()==legacy.hashCode()&&NativeSourceArenaPoison.Viewer.class.getRecordComponents().length==2,"original ctor and record equality/hash/schema exclude new transient proof");check(NativeSourcePoisonAudience.value(null,b.observer(),seen.binding())&&!NativeSourcePoisonAudience.value(Boolean.FALSE,b.observer(),seen.binding()),"unmarked legacy fallback and published missing first receiver differ");check(NativeSourcePoisonAudience.first(new NativeSourceElementAudience.Audience(List.of(),Map.of()),b.observer())==Boolean.FALSE,"published missing first member fails closed");
  byte[] packet=Protocol.poison(f.base().aim().npc().id(),0);for(var pc:List.of(b.viewer(),b.observer())){var v=viewer(p,pc);check(NativeSourceArenaPoison.current(new NativeSourceArenaPoison.Output(p,pc,v.binding())),"original arena poison final output accepts valid first receiver");var q=queue(f,pc,packet);var socket=SourceNpcHpOutputPlan.io(pc);run(q);check(socket.bytes.size()==packet.length+2,"original status queue/task/final cipher emits exact first audience");frames++;}
  Object life=NativeSourceControlledDisplay.rawLife(b.viewer());waitReject(queue(f,b.viewer(),packet),()->CombatAccess.set(state(b.viewer()),"sourceNpcOwner",new Object()),"living receiver revival");CombatAccess.set(state(b.viewer()),"sourceNpcOwner",life);
  waitReject(queue(f,b.observer(),packet),()->CombatAccess.set(b.observer(),"observer",false),"observer becomes living");CombatAccess.set(b.observer(),"observer",true);
  waitReject(queue(f,b.observer(),packet),()->CombatAccess.set(state(b.observer()),"sourceNpcOwner",new Object()),"nullable observer later life");CombatAccess.set(state(b.observer()),"sourceNpcOwner",null);
  var status=CombatAccess.field(b.viewer(),"timedStatus");var replacement=new BattleTimedStatus();set(replacement,"sourcePoisonLifecycle",CombatAccess.field(status,"sourcePoisonLifecycle"));waitReject(queue(f,b.viewer(),packet),()->SourceElementAudiencePlan.replaceStatus(b.viewer(),replacement),"same life in replacement status container");set(b.viewer(),"timedStatus",status);
  waitReject(queue(f,b.viewer(),packet),()->{NativePlayerCommit.scene(b.viewer(),2L,"currentRoomId");NativePlayerCommit.scene(b.viewer(),1L,"currentRoomId");},"actual scene ABA");
  var q=queue(f,b.observer(),packet);set(b.life(),"mode",NativePlayerLifetime.Mode.DRAINING);var socket=SourceNpcHpOutputPlan.io(b.observer());run(q);check(socket.bytes.size()==packet.length+2,"original accepted status allowed in DRAINING");frames++;set(b.life(),"mode",NativePlayerLifetime.Mode.STOPPED);socket=SourceNpcHpOutputPlan.io(b.observer());run(q);check(socket.bytes.size()==0,"original STOPPED fence retained with first proof");set(b.life(),"mode",NativePlayerLifetime.Mode.OPEN);set(b.hub(),"nativeStaticMotionClosed",true);socket=SourceNpcHpOutputPlan.io(b.observer());run(q);check(socket.bytes.size()==0,"original Main closed fence retained with first proof");set(b.hub(),"nativeStaticMotionClosed",false);check(NativeSourceControlledDisplay.rawLife(b.observer())==null,"all queued status transport preserves nullable observer life");firstWait(timed);
 }
 public static void main(String[]args)throws Exception{var area=NativeAreaMaterialAction.current;var oldArea=area.get();var frame=SourceNpcHpOutputPlan.frames();var oldFrame=frame.get();var batches=SourceNpcHpOutputPlan.batches();var oldBatch=batches.get();var rules=CombatRules.class.getDeclaredField("current");rules.setAccessible(true);var oldRules=rules.get(null);var controls=NativeSourceOtherControls.class.getDeclaredField("current");controls.setAccessible(true);var oldControls=controls.get(null);try{area.remove();frame.remove();batches.remove();var path=java.nio.file.Path.of("detached-original-poison-stamp-no-Source-reader");rules.set(null,new CombatRules.Snapshot(Map.of(),path,path,path,Set.of(),path));var props=new Properties();props.setProperty("hpbar","true");controls.set(null,new NativeSourceOtherControls.Snapshot(NativeSourceDisplayPlan.Settings.read(props),path));for(boolean timed:List.of(false,true))test(timed);check(NativeSourcePoisonAudience.class.getDeclaredFields().length==0,"no new root/TLS/registry/worker/queue");var field=NativeSourceArenaPoison.Viewer.class.getDeclaredField("nativeSourcePoisonAudience");check(Modifier.isFinal(field.getModifiers())&&Modifier.isTransient(field.getModifiers()),"one immutable transient noncanonical Viewer slot");check(stamps==4&&captures==18&&frames==6&&waits==10&&discoveryWaits==2,"both natural kinds execute original stamp/queue/final IO/discovery waits");}finally{if(oldArea==null)area.remove();else area.set(oldArea);if(oldFrame==null)frame.remove();else frame.set(oldFrame);if(oldBatch==null)batches.remove();else batches.set(oldBatch);rules.set(null,oldRules);controls.set(null,oldControls);}check(area.get()==oldArea&&frame.get()==oldFrame&&batches.get()==oldBatch&&rules.get(null)==oldRules,"original TLS/rules/controls restored");System.out.println("PASS"+cases+" poison first-audience original-stamp/status-Task/final-cipher contracts; original-stamps="+stamps+", status-captures="+captures+", memory-frames="+frames+", final-receiver-waits="+waits+", first-discovery-waits="+discoveryWaits+"; full poison HP/whole-submit/Source/backend/Main/memory/game/MySQL remain open");}
}
